  str_n26_h10_name = "EX4 - Arrogancia",
  str_n26_h11_name = "EX5 - Subyugación",
  str_n26_h12_name = "EX6 - Contraer",
  str_n26_h1_name_desc = "A veces, solo el ritmo de las olas es suficiente para cambiar la situación en el campo de batalla.",
  str_n26_h2_name_desc = "En las batallas navales, los arrecifes son como trampas que cualquiera de los bandos puede utilizar para reclamar la victoria. Durante las batallas terrestres, los artilugios mecánicos tienen el mismo propósito.",
  str_n26_h3_name_desc = "Escuchar esa voz, ver esa figura... Sabes que no estás solo.",
  str_n26_h4_name_desc = "Custodiar la gloria es custodiar la esperanza. No importa lo que depare el futuro, esta es una verdad innegable.",
  str_n26_h5_name_desc = "Aunque el enemigo enfrentará repercusiones por sus acciones, esto también significa que la batalla se volverá mucho más difícil.",
  str_n26_h6_name_desc = "No te dejes intimidar por la cantidad de enemigos. La mejor manera de eliminar el miedo es enfrentarlo de frente.",
  str_n26_h7_name_desc = "Cuando aparecen más y más enemigos, formando un mar de enemigos, quizás el camino hacia la victoria esté en reducir tu línea defensiva y concentrar tu poder en una resistencia unida.",
  str_n26_h8_name_desc = "Es casi como si tu enemigo tuviera el poder de ganar en cualquier momento, pero preferiría jugar contigo antes que terminar la batalla demasiado pronto...",
  str_n26_h9_name_desc = "Siempre que un enemigo resulte gravemente herido, puedes estar seguro de que su contraataque será aún más frenético que antes.",
  str_n26_h10_name_desc = "Cuando el enemigo está en peligro, pedirá refuerzos a sus aliados. Eliminarlos rápidamente es la única forma de reclamar la victoria.",
  str_n26_h11_name_desc = "Esté preparado para hacer frente a diversas situaciones en el campo de batalla y reprimir al enemigo hasta el final amargo. Desafortunadamente, el enemigo hará exactamente lo mismo.",
  str_n26_h12_name_desc = "Cuando la tierra se hace añicos y no hay adónde huir, ¿cómo podemos encontrar la oportunidad de salir triunfantes?",
  str_n26_1_name = "ST1 - Zarpando",
  str_n26_2_name = "N1 - La familia Lin",
  str_n26_3_name = "N2 - Tormenta",
  str_n26_4_name = "N3 - Señales",
  str_n26_5_name = "N4 - sacudido",
  str_n26_6_name = "N5 - Cola de ratón",
  str_n26_7_name = "N6 - Cabeza de mono",
  str_n26_8_name = "ST2 - Orejas de conejo",
  str_n26_9_name = "N7 - Deserción",
  str_n26_10_name = "N8 - Hambre",
  str_n26_11_name = "N9 - Barco perdido",
  str_n26_12_name = "N10 - A bordo",
  str_n26_13_name = "N11 - La brújula",
  str_n26_14_name = "N12 - Última batalla",
  str_n26_15_name = "ST3 - Recalada",
  str_n26_1_name_desc = "/",
  str_n26_2_name_desc = "Como Zhong Xu, un viejo amigo de la familia Lin, te cuenta más, poco a poco vas armando una impresión más concreta de la familia Lin en tu mente.",
  str_n26_3_name_desc = "Se avecina una tormenta y decides subir a cubierta para ayudar a Yuebai y Liqing. En medio del caos, sientes criaturas inusuales en el mar...",
  str_n26_4_name_desc = "El Shadowind está muy dañado y apenas puede seguir navegando. En esta terrible situación, parece que solo puedes rezar para que los cielos sean benévolos...",
  str_n26_5_name_desc = "Buscar la brújula perdida en las profundidades y cazar las piezas necesarias entre los restos es como tratar de pescar una aguja en el océano... ¿Puedes realmente tener éxito?",
  str_n26_6_name_desc = "Los animales a veces tienen instintos más agudos que los aurorianos y pueden encontrar cosas que no se ven fácilmente a simple vista.",
  str_n26_7_name_desc = "Los animales a veces saben más sobre la cooperación que los aurorianos y pueden transmitir información con precisión a sus amigos de confianza.",
  str_n26_8_name_desc = "/",
  str_n26_9_name_desc = "Debe persistir, ya sea que pueda lograr resultados o no.",
  str_n26_10_name_desc = "El miedo al hambre es un instinto primario. Cada uno debe hacer lo que pueda para aliviar su malestar.",
  str_n26_11_name_desc = "Debes arriesgarte para ver si realmente hay esperanza en algún lugar del vasto océano.",
  str_n26_12_name_desc = "Este no es el Shadowind con el que estás familiarizado. ¿Qué es este lugar, exactamente?",
  str_n26_13_name_desc = "La brújula está justo ahí. Casi puedes tocarlo.",
  str_n26_14_name_desc = "Los animales a veces guardan rencores más profundos que los aurorianos. Todo lo que sufren les será devuelto multiplicado por diez.",
  str_n26_15_name_desc = "/",
  str_n26_1_name_desc_long = "Twin Pavilions Bay está vivo con la atmósfera del Festival de Primavera, un festival tradicional de Longzhou. Tú y los otros pasajeros del Shadowind han estado aquí por un tiempo y finalmente se están preparando para su partida. Sin embargo, en el momento en que Shadowind está a punto de zarpar, Piolín te encuentra de nuevo y te entrega una carta para que la envíes al otro lado del océano. A pedido de Piolín, decides ir al continente de Longzhou en su nombre, embarcándote en el Shadowind.",
  str_n26_2_name_desc_long = "Zhong Xu y Liqing, tus nuevos conocidos de Twin Pavilions Bay, parecen tener alguna conexión con el barco en el que te encuentras. En la mesa de la cena, Zhong Xu cuenta su experiencia a la deriva a Astra hace medio año cuando él y Liqing se encontraron con la desgracia a bordo del Shadowind. Como resultado de ese incidente, el Lin Guildmaster no solo resultó gravemente herido, sino que el orgulloso dispositivo de navegación de la familia Lin, The Compass, se hundió en el mar con el viejo barco.",
  str_n26_3_name_desc_long = "Una turbulencia repentina despierta a cada huésped uno por uno mientras descansan en la cabina. Ha azotado una tormenta. El viento, los truenos y la lluvia claman a tu alrededor. En lugar de seguir al equipo de rescate, te diriges a la cubierta. Yuebai dirige a la tripulación para estabilizar la nave mientras Liqing se encoge hacia un lado por el miedo. Cuando usas tu habilidad psíquica para encontrar a tus compañeros, un banco de peces serpiente comienza a embestir frenéticamente al Shadowind.",
  str_n26_4_name_desc_long = "Después de pasar una noche en una feroz lucha entre la vida y la muerte, el Shadowind queda plagado de agujeros y todas sus secciones importantes del casco se pierden. Afortunadamente, tú y tus compañeros aún estáis vivos, pero la situación es desesperada. Los suministros pronto se acabarán, debes encontrar una manera de navegar una vez más. Li Tianxian, conocido por todos como un charlatán, proporciona tres adivinaciones para Shadowind, lo que le da inspiración a Yuebai.",
  str_n26_5_name_desc_long = "Con la experiencia de Zhong Xu a bordo de un barco que se hunde, decides apostarlo todo a relanzar el Shadowind y comenzar a buscar las piezas que necesitas. Las velas se han dañado, por lo que solo se puede remar manualmente con remos. Si navega lentamente en un clima soleado, aún puede tener la oportunidad de cambiar su destino. Las personas a bordo están conmocionadas, pero Yuebai es muy firme sobre lo que se debe hacer. Si mostrara algún miedo, nadie creería que existiera un solo rastro de esperanza.",
  str_n26_6_name_desc_long = "Todos parten uno tras otro y deciden buscar la veleta que falta, la cola del ratón, a bordo del enorme Shadowind. Dantang también desea hacer algo para ayudar a salvar a Shadowind, pero no sabe nada sobre la cola del ratón. Tianxian aparece con sus dos pájaros parlantes. Dan vueltas en el cielo arriba y encuentran la cola del ratón con facilidad.",
  str_n26_7_name_desc_long = "Liqing insiste en llevar el bote salvavidas al mar solo para salvar una polea apodada \"cabeza de mono\", pero duda debido a su miedo innato al agua. Preocupado, tomas un bote salvavidas y flotas en el mar en calma con él. Liqing sabe claramente a dónde van ustedes dos, y pescan con éxito la cabeza de mono de un naufragio. Él te dice que todo fue gracias a su \"amigo en el mar\".",
  str_n26_8_name_desc_long = "Para reparar Shadowind, comienzas a intentar recuperar partes especiales de barcos hundidos: las orejas de conejo. Se utilizan para cubrir las fugas en el fondo de la nave, aliviando con éxito la presión sobre Shadowind. Hasta ahora, el trabajo de reparación se ha completado en gran parte. Los marineros se reúnen para celebrar y todos comienzan a creer que el resto del viaje será un éxito.",
  str_n26_9_name_desc_long = "A medida que pasa el tiempo, el optimismo de los marineros se desvanece gradualmente. Cada vez surgen más problemas prácticos. Con materiales insuficientes, los miembros de la tripulación se enferman y ahora, otra tormenta bloquea el camino.",
  str_n26_10_name_desc_long = "Los suministros de alimentos se agotan y los marineros no tienen más remedio que pasar más tiempo pescando. Inesperadamente, un pez serpiente es atrapado por accidente, un incidente que casi hace volcar el barco. Liqing le dice apresuradamente a la tripulación que suelte el pez serpiente, evitando un gran desastre. Sin embargo, Zhong Xu ve algo más. Encuentra al capitán solo y anuncia que The Compass está justo adelante.",
  str_n26_11_name_desc_long = "Ves los restos del viejo Shadowind desde la cubierta. Yuebai inmediatamente salta al agua, y tú y Liqing lo siguen de cerca en bote. Pero luego, una niebla repentina desciende sobre el mar, y no se puede ver nada en medio del vasto manto blanco. Yuebai se une a ti y te dice que encontró un barco perdido en el fondo del océano. Mientras vas a la deriva, un enorme barco aparece frente a ti.",
  str_n26_12_name_desc_long = "Abordas el enorme barco en la niebla, solo para encontrar a nadie a bordo. No parece ser Shadowind... Pero solo Liqing lo reconoce. Es el viejo Shadowind. Emocionado, te lleva a buscar La Brújula. Mientras tanto, en el Shadowind actual, Zhong Xu les cuenta a todos sobre los últimos momentos del antiguo Shadowind. Mientras cuenta su historia, un ruido repentino llena el aire: tienen compañía.",
  str_n26_13_name_desc_long = "Mientras buscas The Compass en la cabaña del viejo Shadowind, alguien te encierra de repente dentro de la habitación. Liqing exclama que el culpable es en realidad The Compass: originalmente era un pez serpiente, pero ahora se ha convertido en un juguete con un poder fenomenal. Si no lo atrapas pronto, todos tus esfuerzos habrán sido en vano.",
  str_n26_14_name_desc_long = "Zhong Xu lleva a los demás a abordar el viejo barco y se encuentra con The Compass, ahora un juguete viviente. Está lleno de resentimiento hacia todos los Aurorianos y la nave que lo aprisionó. Intenta enviaros a todos al fondo del océano. Después de una feroz batalla, lo derrotas, pero su odio hace que todos reconsideren sus decisiones. Yuebai lo libera en el mar para corregir los errores del pasado. Shadowind comienza la última etapa de su viaje y tú te diriges a Longzhou. De repente, los peces serpiente emergen del mar y llevan el barco gigante sobre sus espaldas.",
  str_n26_15_name_desc_long = "El Shadowind finalmente atraca con éxito y tu desventura finalmente termina. Pasas el Festival de Primavera con la familia Lin. La carta que trajiste es peculiar, pero tu misión está completa. Unos días después, Yuebai te invita a ver a Shadowind para presenciar su regreso a la gloria. Firmas tu nombre en el barco: Shadowind lo llevará de un lado a otro entre Longzhou y Astra, grabando para siempre tu nombre en el mar.",
  str_n26_food_name_1 = "Pescado al vapor",
  str_n26_food_name_2 = "Bolas de sésamo",
  str_n26_food_name_3 = "Carne de cerdo braseado",
  str_n26_food_name_4 = "camarones",
  str_n26_food_name_5 = "Rollitos de primavera",
  str_n26_food_name_6 = "Albóndigas Sixi",
  str_n26_food_name_7 = "Arroz mezclado",
  str_n26_food_name_8 = "Pizzeta De Tomate",
  str_n26_food_name_9 = "Huevo al vapor",
  str_n26_food_name_10 = "pepitas",
  str_n26_food_name_11 = "Olla chisporroteante",
  str_n26_food_name_12 = "Filete chamuscado",
  str_n26_food_name_13 = "udon",
  str_n26_food_name_14 = "Arroz frito",
  str_n26_food_desc_1 = "Pescado marinado en jengibre y vino de cocina, luego cocido al vapor en una olla. Se le agrega salsa de soya para obtener la cantidad justa de sabor umami.",
  str_n26_food_desc_2 = "Un postre sencillo y delicioso a base de arroz glutinoso y relleno de sésamo negro. Adecuado para jóvenes y mayores por igual.",
  str_n26_food_desc_3 = "Carne de cerdo en cubos cocinada en salsa de soya o azúcar hasta que esté perfectamente dorada. Graso, pero no nauseabundo.",
  str_n26_food_desc_4 = "Empanadillas rellenas de camarones, hervidas en agua y luego colocadas en una vaporera. Elástico y suntuoso, cada bocado está lleno de sabor.",
  str_n26_food_desc_5 = "Rollitos de primavera fritos hasta que estén dorados y crujientes, hechos con carne deshebrada, repollo, tofu y más. Una delicia crujiente con sabores complejos.",
  str_n26_food_desc_6 = "Albóndigas de cerdo y marisco, primero fritas y luego guisadas. La salsa tiene un color vivo, aroma y sabor.",
  str_n26_food_desc_7 = "Arroz e ingredientes variados cocidos en una olla hasta que se forme una capa de arroz crocante en el fondo. El olor es rico e irresistible.",
  str_n26_food_desc_8 = "Una base de harina cubierta con tomates, champiñones y más horneados a la perfección. Apto para compartir.",
  str_n26_food_desc_9 = "Huevos batidos y cocidos al vapor en una olla, luego sazonados con salsa de soya con cebollín para decorar. Aunque simple, es un plato muy popular en Longzhou.",
  str_n26_food_desc_10 = "Pollo cortado en cubitos rebozado y frito hasta que esté dorado por fuera y tierno por dentro.",
  str_n26_food_desc_11 = "Carne de res a la parrilla en olla de hierro, sazonada con salsa de soya dulce. Complementado con champiñones, zanahorias, tofu y otras guarniciones.",
  str_n26_food_desc_12 = "Bistec cortado en el centro, frito en una sartén de hierro con mantequilla hasta que ambos lados estén dorados, servido con salsa de pimienta negra.",
  str_n26_food_desc_13 = "Fideos gruesos hechos de harina, sal y agua. Suele cocinarse en un caldo.",
  str_n26_food_desc_14 = "Arroz rebozado con huevo, salteado hasta que esté dorado. Puede incluir champiñones, guisantes, zanahorias, camarones y más para un rico sabor.",
  str_n26_food_tishi_1 = "Él <color=#b74b25>Harina</color> y <color=#b74b25>Condimento</color> proporción de la porción debe ser 2:1.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_2 = "Él <color=#b74b25>Vegetal</color> y <color=#b74b25>Condimento</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_3 = "El número de <color=#b74b25>Mariscos</color> las porciones deben ser menores que la suma de los otros dos ingredientes.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_4 = "El número de <color=#b74b25>Carne</color> Las porciones deben ser el doble del número de <color=#b74b25>Condimento</color> porciones\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_5 = "El número de <color=#b74b25>Harina</color> las porciones deben ser mayores que la suma de los otros dos ingredientes.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_6 = "Él <color=#b74b25>Mariscos</color> y <color=#b74b25>Vegetal</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_7 = "Él <color=#b74b25>Vegetal</color> y <color=#b74b25>Carne</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_8 = "El número de <color=#b74b25>Harina</color> Las porciones deben ser el doble del número de <color=#b74b25>Vegetal</color> porciones\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_9 = "El número de <color=#b74b25>Carne</color> las porciones deben ser mayores que la suma de los otros tres ingredientes.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_10 = "Él <color=#b74b25>Huevo</color> y <color=#b74b25>Condimento</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_11 = "El número de <color=#b74b25>Arroz</color> las porciones deben ser iguales a la suma de los otros tres ingredientes, y la porción más pequeña debe ser la <color=#b74b25>Huevos</color>.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_12 = "Él <color=#b74b25>Carne</color> y <color=#b74b25>Vegetal</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_13 = "Debería haber uno más <color=#b74b25>Vegetal</color> parte de lo que hay <color=#b74b25>Carne</color> porciones\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_14 = "El número de <color=#b74b25>Harina</color> las porciones deben ser menores que la suma de los otros dos ingredientes.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_15 = "Él <color=#b74b25>Huevo</color> y <color=#b74b25>Harina</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_16 = "El número de <color=#b74b25>Huevo</color> las porciones deben ser mayores que el número de <color=#b74b25>Condimento</color> porciones\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_17 = "El <color=#b74b25>Harina</color> la porción debe ser la suma de los <color=#b74b25>Huevo</color> y <color=#b74b25>Condimento</color> porciones, y la porción más grande debe ser la <color=#b74b25>Carne</color>.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_18 = "Él <color=#b74b25>Huevo</color> y <color=#b74b25>Condimento</color> las porciones deben ser iguales.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_19 = "Debería haber uno más <color=#b74b25>Vegetal</color> parte de lo que hay <color=#b74b25>Condimento</color> porciones\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
  str_n26_food_tishi_20 = "El número de <color=#b74b25>Carne</color> las porciones deben ser mayores que la suma de los otros tres ingredientes.\n<color=#b74b25>Se debe agregar al menos 1 porción de cada ingrediente.</color>",
